 3	public final class DynamicProgrammingCoinChangeSolver implements CoinChangeSolver {
 4	
 5	    @Override
 6	    public int countWays(CoinChangeRequest request) {
 7	        int targetSum = request.targetSum();
 8	        int[] waysBySum = new int[targetSum + 1];
 9	        waysBySum[0] = 1;
10	
11	        for (int coin : request.denominations().values()) {
12	            for (int currentSum = coin; currentSum <= targetSum; currentSum++) {
13	                waysBySum[currentSum] += waysBySum[currentSum - coin];
14	            }
15	        }
16	
17	        return waysBySum[targetSum];
18	    }
19	}

